is_oa": true, "oa_status": "bronze", "oa_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/tops.12196", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1111/tops.12196", "doi": "https://doi.org/10.1111/tops.12196", "is_oa": true, "landing_page_url": "https://doi.org/10.1111/tops.12196", "pdf_url": "https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/tops.12196", "source": {"id": "https://openalex.org/S22283869", "display_name": "Topics in Cognitive Science", "issn_l": "1756-8757", "issn": ["1756-8757", "1756-8765"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["anvur-scientific", "cwts-core", "dongbi-b", "jufo-1", "medline", "norway-1", "poland-100", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310320595", "host_organization_name": "Wiley", "host_organization_lineage": ["https://openalex.org/P4310320595"], "host_organization_lineage_names": ["Wiley"], "type": "journal"}, "license": null, "license_id": null, "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "Topics in Cognitive Science", "raw_type": "journal-article"}, "abstract": "Infants' own activities create and actively select their learning experiences. Here we review recent models of embodied information seeking and curiosity-driven learning and show that these mechanisms have deep implications for development and evolution. We discuss how these mechanisms yield self-organized epigenesis with emergent ordered behavioral and cognitive developmental stages. We describe a robotic experiment that explored the hypothesis that progress in learning, in and for itself, generates intrinsic rewards: The robot learners probabilistically selected experiences according to their potential for reducing uncertainty. In these experiments, curiosity-driven learning led the robot learner to successively discover object affordances and vocal interaction with its peers. We explain how a learni